import pytest

from anatomy import fit as F

MODELS = {"a": 0.4, "b": 1.0, "c": 2.5, "d": 6.0}  # GPU ms at batch 1
SIX = {**MODELS, "e": 12.0, "f": 25.0}  # enough models for the model bootstrap (fit.MIN_BOOT_MODELS)


def cells(form, h0=1.0, h1=0.01, arm="defaults", noise=0.0, models=MODELS):
    """Cells generated by a known host model and GPU times growing with batch (KV reads)."""
    rows = []
    for i, (m, g1) in enumerate(models.items()):
        for b in (1, 4, 16, 64, 256):
            g = g1 + 0.004 * b * (i + 1)
            host = h0 + h1 * b
            step = (host + g if form == "serial" else max(host, g)) * (1 + noise * ((b % 3) - 1))
            rows.append({"engine": "e", "arm": arm, "level": "L1", "model": m, "batch": b, "step_ms": step,
                         "occupied": g / step, "kernel_ms": g * 0.9, "floor_ms": g * 0.6, "kernel_exc_ms": g * 0.3,
                         "launch_ms": g * 0.1})
    return rows


@pytest.mark.parametrize("form", ["overlapped", "serial"])
def test_recovers_the_generating_form_and_host_model(form):
    f = F.fit(cells(form))
    assert f["form"] == form
    assert f["h0_ms"] == pytest.approx(1.0, abs=1e-6) and f["h1_ms"] == pytest.approx(0.01, abs=1e-6)
    assert f["median_error"] == pytest.approx(0, abs=1e-9)


def test_overlapped_engine_with_slack_is_not_mistaken_for_serial():
    """Most cells are GPU-bound, where both forms predict well; an overlapped engine with 2% slack per step must still
    come out overlapped, decided by the host-bound cells (the reason selection uses RMS, not the median)."""
    rows = cells("overlapped", h0=1.4, h1=0.006)
    for r in rows:
        r["step_ms"] *= 1.02
        r["occupied"] /= 1.02
    f = F.fit(rows)
    assert f["form"] == "overlapped" and f["h0_ms"] == pytest.approx(1.4 * 1.02, rel=0.05)


def test_overlapped_fit_uses_only_host_bound_cells():
    _, n = F.fit_form(cells("overlapped"), "overlapped")
    host_bound = sum(1 for r in cells("overlapped") if (r["step_ms"] - F.gpu_ms(r)) >= 0.05 * r["step_ms"])
    assert n == host_bound and 0 < n < len(cells("overlapped"))


def test_leave_one_model_out_is_small_on_clean_data_and_reported_per_model():
    lomo = F.leave_one_model_out(cells("serial", noise=0.01))
    assert set(lomo["per_model"]) == set(MODELS) and lomo["median"] < 0.02


def test_the_host_cost_carries_an_interval_and_its_held_out_error():
    f = F.fit(cells("overlapped", noise=0.01), offset_sd=0.005)
    lo, hi = f["h0_interval"]
    assert lo <= f["h0_ms"] <= hi and f["h1_interval"][0] <= f["h1_ms"] <= f["h1_interval"][1]
    assert f["lomo"]["median"] is not None and f["lomo"]["cells"] > 0
    again = F.fit(cells("overlapped", noise=0.01), offset_sd=0.005)
    assert again["h0_interval"] == [lo, hi]  # a fixed seed: the page rebuilds the same


def test_one_host_bound_model_never_gives_a_zero_width_interval():
    """Six models, only the smallest waiting on the host: resampling whole models draws that one model every time, and
    gave a '90% interval' of zero width (1.40-1.40) whose sign verdicts followed noise. With so few models the
    interval comes from that model's cells and a process offset at the measured noise, or is not identified, and then
    h1's sign is never judged from it."""
    rows = [r for r in cells("overlapped", h0=1.0, h1=0.0, noise=0.004, models=SIX)
            if r["model"] == "a" or not F.host_bound(r)]
    assert len({r["model"] for r in rows if F.host_bound(r)}) == 1
    f = F.fit(rows, offset_sd=0.005)
    assert f["interval_method"] == "cells and process offsets" and f["h0_interval"][1] > f["h0_interval"][0]
    blind = F.fit(rows)
    assert blind["h1_interval"] is None and blind["interval_method"] is None and blind["unphysical"] is None


def test_too_few_host_bound_cells_identify_no_host_cost():
    rows = [r for r in cells("overlapped") if not F.host_bound(r) or r["batch"] == 1]  # host-bound at one batch only
    f = F.fit(rows)
    assert f["form"] == "too few host-bound cells" and f["h0_ms"] is None and f["n_host_cells"] > 0


def test_faster_memory_shrinks_gpu_time_and_moves_cells_towards_host_bound():
    rows = cells("overlapped")
    f = F.fit(rows, offset_sd=0.005)
    now = F.predict(rows, f, 1.0)
    faster = F.predict(rows, f, 2.0)
    assert all(b["occupied"] <= a["occupied"] + 1e-12 for a, b in zip(now, faster))
    assert sum(b["occupied"] < 0.9 for b in faster) > sum(a["occupied"] < 0.9 for a in now)


def test_an_engine_that_never_waits_on_the_host_is_not_given_a_host_cost():
    rows = cells("overlapped", h0=0.05, h1=0.0)  # host far below every GPU time: no cell is host-bound
    f = F.fit(rows)
    assert f["form"] == "not host-bound" and f["h0_ms"] is None
    assert f["host_upper_bound_ms"][1] == pytest.approx(0.4 + 0.004)  # the smallest model's GPU time at batch 1
    assert f["lomo"]["median"] is None


def test_no_prediction_without_kernel_time():
    rows = cells("overlapped")
    for r in rows[::2]:
        r["floor_ms"] = None  # no node capture at this batch
    f = F.fit(rows, offset_sd=0.005)
    assert len(F.predict(rows, f, 2.0)) == len(rows) // 2


def test_no_usable_cells():
    assert F.fit([{"engine": "e", "arm": "defaults", "level": "L1", "model": "a", "batch": 1, "step_ms": None,
                   "occupied": None}]) is None


def test_a_host_time_falling_with_the_batch_is_never_clamped_into_the_fixed_cost():
    """The old fit set a negative slope to 0 and moved it into h0 without saying so. Clearly negative, it is no host
    model (unphysical, no scenario); within its interval of 0, it is fixed at 0, and the fit says so."""
    falling = F.fit(cells("serial", h0=2.0, h1=-0.004, models=SIX))
    assert falling["unphysical"] and "falls as the batch grows" in falling["unphysical"]
    assert falling["interval_method"] == "models"
    assert F.predict(cells("serial", h0=2.0, h1=-0.004, models=SIX), falling, 2.0) == []
    rows = cells("serial", h0=1.0, h1=-0.00002, models=SIX)
    slopes = dict(zip(SIX, (0.0005, -0.0005, 0.0003, -0.0003, 0.0004, -0.0004)))  # each process its own slope
    for r in rows:
        r["step_ms"] += slopes[r["model"]] * r["batch"]
        r["occupied"] = r["kernel_ms"] / 0.9 / r["step_ms"]
    flat = F.fit(rows)
    assert flat["h1_interval"][0] < 0 <= flat["h1_interval"][1] and flat["h1_fixed_at_zero"] and flat["h1_ms"] == 0.0
    assert flat["unphysical"] is None


def test_residuals_are_apart_by_regime_and_the_scenario_carries_its_band():
    rows = cells("overlapped", noise=0.01)
    f = F.fit(rows, offset_sd=0.005)
    assert set(f["residuals"]) == {"host-bound", "gpu-bound"} and f["residuals"]["host-bound"]["cells"] > 0
    for p in F.predict(rows, f, 2.0):
        assert p["occupied_lo"] <= p["occupied"] + 1e-12 <= p["occupied_hi"] + 2e-12
    fitted = {b for b, _ in F.points(rows, f["form"])}
    assert any(p["extrapolated"] for p in F.predict(rows, f, 2.0)) == (fitted != {1, 4, 16, 64, 256})
